"""Chart of accounts: paths, types, patterns."""
import re

from .currency import CURRENCIES
from .dates import is_date
from .errors import ConflictError, NotFoundError, ValidationError
from .model import Account


class ChartError(ValidationError):
    pass


class _ChartConflict(ChartError, ConflictError):
    code = "conflict"


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEG_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEG_RE.fullmatch(p) for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path '%s'" % (path,))


def parent_path(path):
    _need_path(path)
    head, sep, _ = path.rpartition(":")
    return head if sep else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern '%s'" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and not _SEG_RE.fullmatch(p):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern parts, segs: list of path segments; full match
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for n in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[n:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pattern:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segments(parts, path.split(":"))


def _sort_key(path):
    return tuple(path.split(":"))


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        kind = ROOT_TYPES[path.split(":", 1)[0]]
        if type is not None and type != kind:
            if type not in TYPES:
                raise ChartError("unknown account type '%s'" % (type,))
            raise ChartError("account %s is of type %s, not %s" % (path, kind, type))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency '%s'" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got '%s'" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text")
        if path in self._explicit:
            raise _ChartConflict("account %s already exists" % path)
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            self._explicit.add(path)
            return existing
        parts = path.split(":")
        for i in range(1, len(parts)):
            p = ":".join(parts[:i])
            if p not in self._accounts:
                self._accounts[p] = Account(p, ROOT_TYPES[parts[0]])
        acct = Account(path, kind, currency, opened, None, note)
        self._accounts[path] = acct
        self._explicit.add(path)
        return acct

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account '%s'" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def children(self, path):
        self.get(path)
        n = path.count(":") + 1
        return [a for a in self.accounts() if a.path.startswith(path + ":") and a.path.count(":") == n]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        a = self.get(path)
        if not is_date(on):
            raise ChartError("not a date: '%s'" % (on,))
        return (a.opened is None or a.opened <= on) and (a.closed is None or on <= a.closed)

    def close(self, path, on):
        a = self.get(path)
        if not is_date(on):
            raise ChartError("closing date must be a date, got '%s'" % (on,))
        if a.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if a.opened is not None and on < a.opened:
            raise ChartError("account %s cannot close before it opened on %s" % (path, a.opened.isoformat()))
        a.closed = on
        return a

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]
"""The ledger: validated transactions and balances."""
import re
from collections import defaultdict
from datetime import date

from .accounts import Chart
from .currency import RateTable
from .dates import is_date
from .errors import NotFoundError, ValidationError
from .model import Posting, Transaction
from .money import Money, format_minor


class LedgerError(ValidationError):
    pass


_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _text(value, what):
    if not isinstance(value, str) or "\n" in value or "\r" in value:
        raise LedgerError("%s must be text without a line break" % what)


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -------------------------------------------------------
    def _build(self, tx, tx_id):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, got '%s'" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("flag must be '*' or '!', got '%s'" % (tx.flag,))
        _text(tx.payee, "payee")
        _text(tx.narration, "narration")
        if isinstance(tx.tags, str) or not hasattr(tx.tags, "__iter__"):
            raise LedgerError("tags must be a list of names")
        tags = set()
        for t in tx.tags:
            if not isinstance(t, str) or not _TAG_RE.fullmatch(t):
                raise LedgerError("invalid tag '%s'" % (t,))
            tags.add(t.lower())
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: '%s'" % (p,))
            if not isinstance(p.account, str):
                raise LedgerError("posting account must be text")
            _text(p.note, "posting note")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be money or None")
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account '%s'" % p.account)
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, tx.date.isoformat()))
            if p.amount is not None:
                self._check_currency(p)
        blanks = [i for i, p in enumerate(postings) if p.amount is None]
        if len(blanks) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = defaultdict(int)
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] += p.amount.minor
        if blanks:
            i = blanks[0]
            off = sorted(c for c, v in sums.items() if v != 0)
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            old = postings[i]
            new = [Posting(old.account, Money(-sums[c], c), old.note) for c in off]
            for p in new:
                self._check_currency(p)
            postings[i : i + 1] = new
            sums = defaultdict(int)
            for p in postings:
                sums[p.amount.currency] += p.amount.minor
        bad = sorted(c for c, v in sums.items() if v != 0)
        if bad:
            raise LedgerError(
                "transaction does not balance: "
                + ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in bad)
            )
        return Transaction(tx.date, tx.payee, tx.narration, postings, tuple(sorted(tags)), tx.flag, tx_id)

    def _check_currency(self, p):
        want = self.chart.get(p.account).currency
        if want is not None and p.amount.currency != want:
            raise LedgerError(
                "account %s only holds %s, not %s" % (p.account, want, p.amount.currency)
            )

    def _assign_id(self, tx):
        if tx.id is None:
            return self._max_id + 1
        if not _is_int(tx.id) or tx.id < 1:
            raise LedgerError("transaction id must be an integer of at least 1, got '%s'" % (tx.id,))
        if tx.id in self._txs:
            raise LedgerError("transaction %d already exists" % tx.id)
        return tx.id

    # -- mutation ---------------------------------------------------------
    def add(self, tx):
        if isinstance(tx, Transaction):
            tx_id = self._assign_id(tx)
        else:
            tx_id = None
        stored = self._build(tx, tx_id)
        self._txs[stored.id] = stored
        self._max_id = max(self._max_id, stored.id)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        stored = self._build(tx, id)
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- lookup -----------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    # -- balances ---------------------------------------------------------
    def _walk(self, as_of):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, got '%s'" % (as_of,))
        for tx, p in self.postings():
            if as_of is None or tx.date <= as_of:
                yield p

    @staticmethod
    def _clean(acc):
        out = {}
        for a, cur in acc.items():
            cur = {c: v for c, v in cur.items() if v != 0}
            if cur:
                out[a] = cur
        return out

    def balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            acc[p.account][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def rollup_balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            parts = p.account.split(":")
            for i in range(1, len(parts) + 1):
                acc[":".join(parts[:i])][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account '%s'" % (account,))
        sums = defaultdict(int)
        for p in self._walk(as_of):
            if p.account == account or (rollup and p.account.startswith(account + ":")):
                sums[p.amount.currency] += p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}
