                raise ConflictError("a recurring item named '%s' already exists" % rec.name)
            self._conn.execute(
                "INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count)"
                " VALUES (?, ?, ?, ?, ?, ?)",
                (rec.name, str(rec.schedule), template, format_date(rec.start),
