    @_guard
    def load_journal(self, journal):
        for attr in ("accounts", "rates", "transactions"):
            if not hasattr(journal, attr):
                raise ValidationError("not a journal: '%s'" % (journal,))
        with self._txn(True):
            chart, paths = self._load_chart()
            led = Ledger(chart, self._load_rates())
            new_accounts = []
            for acct in journal.accounts:
                if not isinstance(acct, Account):
                    raise ValidationError("not an account: '%s'" % (acct,))
                if acct.path in paths:
                    raise ConflictError("account %s already exists" % acct.path)
                chart.add(acct.path, acct.type, acct.currency, acct.opened, acct.note)
                if acct.closed is not None:
                    chart.close(acct.path, acct.closed)
                paths.add(acct.path)
                new_accounts.append(chart.get(acct.path))
            rates = list(journal.rates)
            for src, dst, on, text in rates:
                led.rates.set(src, dst, text, on)
            checked = [self._validated(led, paths, tx) for tx in journal.transactions]
            for acct in new_accounts:
                self._conn.execute(
                    "INSERT INTO accounts (path, type, currency, opened, closed, note) VALUES (?, ?, ?, ?, ?, ?)",
                    (acct.path, acct.type, acct.currency,
                     format_date(acct.opened) if acct.opened else None,
                     format_date(acct.closed) if acct.closed else None, acct.note),
                )
            for src, dst, on, text in rates:
                self._conn.execute(
                    "INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                    (src, dst, format_date(on), text),
                )
            return [self._insert(tx) for tx in checked]

    # -- health, backup, status ------------------------------------------
    @_guard
    def check(self):
        problems = set()
        conn = self._conn
        with self._txn(False):
            try:
                for (msg,) in conn.execute("PRAGMA integrity_check").fetchall():
                    if msg != "ok":
                        problems.add("integrity check: %s" % msg)
                for tx_id, n in conn.execute(
                    "SELECT tx_id, count(*) FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"
                    " GROUP BY tx_id"
                ):
                    problems.add("transaction %s is missing but %d posting(s) point to it" % (tx_id, n))
                for tx_id, n in conn.execute(
                    "SELECT tx_id, count(*) FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"
                    " GROUP BY tx_id"
                ):
                    problems.add("transaction %s is missing but %d tag(s) point to it" % (tx_id, n))
                for key, tx_id in conn.execute(
                    "SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)"
                ):
                    problems.add("import key '%s' points to missing transaction %s" % (key, tx_id))
                for (tx_id,) in conn.execute(
                    "SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"
                ):
                    problems.add("transaction %s has no postings" % tx_id)
                for account, n in conn.execute(
                    "SELECT account, count(*) FROM postings WHERE account NOT IN (SELECT path FROM accounts)"
                    " GROUP BY account"
                ):
                    problems.add("%d posting(s) are on account '%s', which is not stored" % (n, account))
                sums = {}
                for tx_id, cur, minor in conn.execute(
                    "SELECT p.tx_id, p.currency, p.minor FROM postings p JOIN transactions t ON t.id = p.tx_id"
                ):
                    if not _is_int(minor):
                        problems.add("transaction %s has an amount that is not a whole number: %r" % (tx_id, minor))
                        continue
                    sums[(tx_id, cur)] = sums.get((tx_id, cur), 0) + minor
                for (tx_id, cur), total in sums.items():
                    if total != 0:
                        shown = format_minor(total, cur) if cur in CURRENCIES else str(total)
                        problems.add("transaction %s does not balance: %s %s" % (tx_id, cur, shown))
            except sqlite3.Error as exc:
                problems.add("cannot read the book: %s" % exc)
        return sorted(problems)

    @_guard
    def backup(self, dest):
        try:
            target = os.fspath(dest)
        except TypeError:
            raise ValidationError("destination must be text or a path object, got '%s'" % (dest,)) from None
        if isinstance(target, bytes):
            target = os.fsdecode(target)
        if not target:
            raise NotFoundError("no such directory for the backup")
        if os.path.lexists(target):
            raise ConflictError("'%s' already exists" % target)
        parent = os.path.dirname(os.path.abspath(target))
        if not os.path.isdir(parent):
            raise NotFoundError("the directory for '%s' does not exist" % target)
        try:
            fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
        except FileExistsError:
            raise ConflictError("'%s' already exists" % target) from None
        except OSError as exc:
            raise ConflictError("cannot create '%s': %s" % (target, exc.strerror or exc)) from None
        os.close(fd)
        try:
            out = sqlite3.connect(target, isolation_level=None)
            try:
                self._conn.backup(out)
            finally:
                out.close()
        except BaseException:
            self._discard(target)
            raise

    @_guard
    def info(self):
        with self._txn(False):
            counts = {}
            for table in ("accounts", "transactions", "postings", "rates", "budgets", "recurring"):
                counts[table] = self._conn.execute("SELECT count(*) FROM %s" % table).fetchone()[0]
        counts["path"] = self.path
        counts["version"] = self._version
        return counts

