"""The book file: one SQLite database with numbered schema versions."""
import contextlib
import functools
import json
import os
import re
import sqlite3
import threading
from collections import Counter
from dataclasses import dataclass, field, replace
from datetime import timedelta

from .accounts import ROOT_TYPES, TYPES, Chart
from .currency import CURRENCIES, RateTable
from .dates import format_date, is_date, parse_date
from .errors import ConflictError, NotFoundError, TallybookError, ValidationError
from .ledger import Ledger, LedgerError
from .model import Account, Posting, Transaction
from .money import Money, format_minor

LATEST_VERSION = 4
BUSY_TIMEOUT = 5.0

_INT_MIN = -(2 ** 63)
_INT_MAX = 2 ** 63 - 1
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS_RE = re.compile(r"[A-Za-z0-9_-]+")
_CURRENCY_RE = re.compile(r"[A-Za-z]{3}")
_PROFILE_PREFIX = "profile."

_STEP1 = [
    "CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, opened TEXT,"
    " note TEXT NOT NULL DEFAULT '')",
    "CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL,"
    " payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)",
    "CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT,"
    " tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,"
    " seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path),"
    " minor INTEGER NOT NULL, currency TEXT NOT NULL)",
    "CREATE INDEX transactions_date_id ON transactions (date, id)",
    "CREATE INDEX postings_tx_seq ON postings (tx_id, seq)",
]
_STEP2 = [
    "CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,"
    " tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))",
    "ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'",
    "ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''",
]
_STEP3 = [
    "CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL,"
    " rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))",
    "ALTER TABLE accounts ADD COLUMN closed TEXT",
]
_STEP4 = [
    "CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL,"
    " currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))",
    "CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL,"
    " start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)",
    "CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)",
    "CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    "CREATE TABLE import_keys (key TEXT PRIMARY KEY,"
    " tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)",
]


class _StepFailed(Exception):
    pass


def _run_all(conn, statements):
    for sql in statements:
        conn.execute(sql)


def _step1(conn):
    _run_all(conn, _STEP1)


def _step2(conn):
    bad = conn.execute(
        "SELECT id, cleared FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1)"
        " ORDER BY id LIMIT 1"
    ).fetchone()
    if bad is not None:
        raise _StepFailed("transaction %s has cleared value %r, expected 0 or 1" % (bad[0], bad[1]))
    _run_all(conn, _STEP2)
    conn.execute("UPDATE transactions SET flag = CASE cleared WHEN 1 THEN '*' ELSE '!' END")


def _clean_currency(value, what, allow_empty):
    if not isinstance(value, str):
        raise _StepFailed("%s has an invalid currency %r" % (what, value))
    cleaned = value.strip()
    if not cleaned:
        if allow_empty:
            return None
        raise _StepFailed("%s has an empty currency" % what)
    if not _CURRENCY_RE.fullmatch(cleaned):
        raise _StepFailed("%s has an invalid currency '%s'" % (what, value))
    return cleaned.upper()


def _step3(conn):
    _run_all(conn, _STEP3)
    for path, cur in conn.execute("SELECT path, currency FROM accounts WHERE currency IS NOT NULL").fetchall():
        cleaned = _clean_currency(cur, "account %s" % path, True)
        if cleaned != cur:
            conn.execute("UPDATE accounts SET currency = ? WHERE path = ?", (cleaned, path))
    for (cur,) in conn.execute("SELECT DISTINCT currency FROM postings").fetchall():
        cleaned = _clean_currency(cur, "a posting", False)
        if cleaned != cur:
            conn.execute("UPDATE postings SET currency = ? WHERE currency = ?", (cleaned, cur))


def _step4(conn):
    _run_all(conn, _STEP4)


_STEPS = {1: _step1, 2: _step2, 3: _step3, 4: _step4}


@dataclass
class BulkAdd:
    added: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: list = field(default_factory=list)
    duplicates: list = field(default_factory=list)
    errors: list = field(default_factory=list)


def _db_error(exc):
    text = str(exc)
    low = text.lower()
    if "locked" in low or "busy" in low:
        return ConflictError("database is locked: another process is writing to the book")
    return ConflictError("database error: %s" % text)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _need_text(value, what):
    if not isinstance(value, str):
        raise ValidationError("%s must be text, got '%s'" % (what, value))
    return value


def _fit(value, what):
    if not _INT_MIN <= value <= _INT_MAX:
        raise ValidationError("%s is too large to store in a book" % what)


def _parse_stored_date(text, what):
    try:
        return parse_date(text)
    except TallybookError:
        raise ConflictError("the book holds an invalid date '%s' (%s)" % (text, what)) from None


def _guard(fn):
    @functools.wraps(fn)
    def wrapper(self, *args, **kwargs):
        with self._lock:
            self._check_usable()
            try:
                return fn(self, *args, **kwargs)
            except sqlite3.Error as exc:
                raise _db_error(exc) from None
            except OverflowError:
                raise ValidationError("a number is too large to store in a book") from None
            except UnicodeEncodeError:
                raise ValidationError("text cannot be stored in a book (invalid characters)") from None

    return wrapper


def _import_key_base(tx):
    first = tx.postings[0]
    return "%s|%s|%s|%d %s" % (
        format_date(tx.date), tx.payee, first.account, first.amount.minor, first.amount.currency
    )


class Store:
    def __init__(self, path, fspath, conn):
        self.path = path
        self._fspath = fspath
        self._conn = conn
        self._lock = threading.RLock()
        self._closed = False
        self._in_tx = False
        self._version = conn.execute("PRAGMA user_version").fetchone()[0]

    # -- opening ---------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        try:
            fspath = os.fspath(path)
        except TypeError:
            raise ValidationError("path must be text or a path object, got '%s'" % (path,)) from None
        if isinstance(fspath, bytes):
            fspath = os.fsdecode(fspath)
        if not fspath:
            raise NotFoundError("no such book file ''")
        if os.path.isdir(fspath):
            raise ConflictError("'%s' is a directory, not a book" % fspath)
        existed = os.path.exists(fspath)
        if not existed:
            if not create:
                raise NotFoundError("no such book file '%s'" % fspath)
            parent = os.path.dirname(os.path.abspath(fspath))
            if not os.path.isdir(parent):
                raise NotFoundError("the directory for '%s' does not exist" % fspath)
        try:
            conn = sqlite3.connect(
                fspath, timeout=BUSY_TIMEOUT, isolation_level=None, check_same_thread=False
            )
        except sqlite3.Error as exc:
            raise ConflictError("cannot open '%s': %s" % (fspath, exc)) from None
        try:
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT count(*) FROM sqlite_master").fetchone()[0]
        except sqlite3.Error as exc:
            conn.close()
            if not existed:
                cls._discard(fspath)
            raise ConflictError("'%s' is not a tallybook book: %s" % (fspath, exc)) from None
        if version == 0 and tables > 0:
            conn.close()
            raise ConflictError("'%s' is not a tallybook book: it has tables but no version" % fspath)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError(
                "'%s' is at version %d, newer than this tool (version %d)" % (fspath, version, LATEST_VERSION)
            )
        store = cls(path, fspath, conn)
        if version == 0 and create:
            try:
                store.migrate()
            except BaseException:
                store.close()
                if not existed:
                    cls._discard(fspath)
                raise
        return store

    @staticmethod
    def _discard(fspath):
        for suffix in ("", "-journal"):
            with contextlib.suppress(OSError):
                os.unlink(fspath + suffix)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        with self._lock:
            if self._closed:
                return
            self._closed = True
            with contextlib.suppress(sqlite3.Error):
                self._conn.close()

    def _check_usable(self):
        if self._closed:
            raise ConflictError("the book is closed")
        if self._version != LATEST_VERSION:
            self._version = self._read_version()
        if self._version != LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % self._version)

    def _read_version(self):
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.Error as exc:
            raise _db_error(exc) from None

    @property
    def version(self):
        with self._lock:
            if self._closed:
                raise ConflictError("the book is closed")
            if self._version != LATEST_VERSION:
                self._version = self._read_version()
            return self._version

    # -- transactions ----------------------------------------------------
    @contextlib.contextmanager
    def _txn(self, write):
        if self._in_tx:
            yield
            return
        self._conn.execute("BEGIN IMMEDIATE" if write else "BEGIN")
        self._in_tx = True
        try:
            yield
            self._conn.execute("COMMIT")
        except BaseException:
            with contextlib.suppress(sqlite3.Error):
                self._conn.execute("ROLLBACK")
            raise
        finally:
            self._in_tx = False

    def migrate(self):
        with self._lock:
            if self._closed:
                raise ConflictError("the book is closed")
            try:
                current = self._read_version()
                applied = []
                for n in range(current + 1, LATEST_VERSION + 1):
                    try:
                        with self._txn(True):
                            _STEPS[n](self._conn)
                            self._conn.execute("PRAGMA user_version = %d" % n)
                    except _StepFailed as exc:
                        raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
                    except sqlite3.Error as exc:
                        raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
                    self._version = n
                    applied.append(n)
                return applied
            finally:
                self._version = self._read_version()

    # -- accounts --------------------------------------------------------
    def _load_chart(self):
        chart = Chart()
        paths = set()
        rows = self._conn.execute(
            "SELECT path, currency, opened, closed, note FROM accounts ORDER BY path"
        ).fetchall()
        for path, cur, opened, closed, note in rows:
            cur = cur or None
            opened_d = _parse_stored_date(opened, "account %s" % path) if opened else None
            known = cur if cur in CURRENCIES else None
            try:
                acct = chart.add(path, None, known, opened_d, note if isinstance(note, str) else "")
            except TallybookError as exc:
                raise ConflictError("the book holds an invalid account '%s': %s" % (path, exc.message)) from None
            acct.currency = cur
            if closed:
                acct.closed = _parse_stored_date(closed, "account %s" % path)
            paths.add(path)
        return chart, paths

    def _stored_account(self, chart, paths, path):
        if not isinstance(path, str) or path not in paths:
            raise NotFoundError("no such account '%s'" % (path,))
        return chart.get(path)

    @_guard
    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._txn(True):
            chart, _ = self._load_chart()
            acct = chart.add(path, type, currency, opened, note)
            self._conn.execute(
                "INSERT INTO accounts (path, type, currency, opened, note) VALUES (?, ?, ?, ?, ?)",
                (acct.path, acct.type, acct.currency, format_date(opened) if opened else None, acct.note),
            )
            return acct

    @_guard
    def get_account(self, path):
        with self._txn(False):
            chart, paths = self._load_chart()
            return self._stored_account(chart, paths, path)

    @_guard
    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return self._accounts(type, under, currency, include_closed)

    def _accounts(self, type, under, currency, include_closed):
        if type is not None and (not isinstance(type, str) or type not in TYPES):
            raise ValidationError("unknown account type '%s'" % (type,))
        if under is not None:
            _need_text(under, "under")
        if currency is not None:
            _need_text(currency, "currency")
        chart, paths = self._load_chart()
        out = []
        for path in sorted(paths):
            acct = chart.get(path)
            if type is not None and acct.type != type:
                continue
            if under is not None and not (path == under or path.startswith(under + ":")):
                continue
            if currency is not None and acct.currency != currency:
                continue
            if not include_closed and acct.closed is not None:
                continue
            out.append(acct)
        return out

    @_guard
    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        with self._txn(False):
            return len(self._accounts(type, under, currency, include_closed))

    @_guard
    def chart(self):
        with self._txn(False):
            return self._load_chart()[0]

    @_guard
    def close_account(self, path, on):
        with self._txn(True):
            chart, paths = self._load_chart()
            self._stored_account(chart, paths, path)
            acct = chart.close(path, on)
            latest = self._conn.execute(
                "SELECT max(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id WHERE p.account = ?",
                (path,),
            ).fetchone()[0]
            if latest is not None and latest > format_date(on):
                raise ConflictError(
                    "cannot close account %s on %s: it has a posting on %s" % (path, format_date(on), latest)
                )
            self._conn.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
            return acct

    @_guard
    def set_account_note(self, path, note):
        _need_text(note, "note")
        with self._txn(True):
            chart, paths = self._load_chart()
            acct = self._stored_account(chart, paths, path)
            self._conn.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            acct.note = note
            return acct

    @_guard
    def delete_account(self, path):
        with self._txn(True):
            _, paths = self._load_chart()
            if not isinstance(path, str) or path not in paths:
                raise NotFoundError("no such account '%s'" % (path,))
            used = self._conn.execute("SELECT count(*) FROM postings WHERE account = ?", (path,)).fetchone()[0]
            if used:
                raise ConflictError("account %s cannot be deleted: %d posting(s) use it" % (path, used))
            self._conn.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # -- transactions ----------------------------------------------------
    def _load(self, cond="", params=(), limit=None, offset=0):
        lim = -1 if limit is None else min(limit, _INT_MAX)
        off = min(offset, _INT_MAX)
        sub = "SELECT id FROM transactions %s ORDER BY date, id LIMIT ? OFFSET ?" % cond
        args = tuple(params) + (lim, off)
        rows = self._conn.execute(
            "SELECT id, date, payee, narration, flag FROM transactions %s ORDER BY date, id LIMIT ? OFFSET ?" % cond,
            args,
        ).fetchall()
        postings = {}
        for tx_id, account, minor, cur, note in self._conn.execute(
            "SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) ORDER BY tx_id, seq" % sub,
            args,
        ):
            try:
                amount = Money(minor, cur)
            except TallybookError as exc:
                raise ConflictError("transaction %s has an invalid amount: %s" % (tx_id, exc.message)) from None
            postings.setdefault(tx_id, []).append(Posting(account, amount, note))
        tags = {}
        for tx_id, tag in self._conn.execute(
            "SELECT tx_id, tag FROM tags WHERE tx_id IN (%s) ORDER BY tx_id, tag" % sub, args
        ):
            tags.setdefault(tx_id, []).append(tag)
        out = []
        for tx_id, day, payee, narration, flag in rows:
            out.append(
                Transaction(
                    _parse_stored_date(day, "transaction %s" % tx_id),
                    payee,
                    narration,
                    postings.get(tx_id, []),
                    tuple(tags.get(tx_id, ())),
                    flag,
                    tx_id,
                )
            )
        return out

    def _validated(self, led, paths, tx):
        if isinstance(tx, Transaction):
            tx = replace(tx, id=None)
        try:
            stored = led.add(tx)
        except TallybookError:
            raise
        except Exception as exc:
            raise LedgerError("invalid transaction: %s" % exc) from None
        led.remove(stored.id)
        for p in stored.postings:
            if p.account not in paths:
                raise LedgerError("unknown account '%s'" % p.account)
            _fit(p.amount.minor, "the amount of a posting to %s" % p.account)
        return stored

    def _insert(self, tx):
        conn = self._conn
        cur = conn.execute(
            "INSERT INTO transactions (date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
            (format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0, tx.flag),
        )
        tx_id = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            conn.execute(
                "INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                (tx_id, seq, p.account, p.amount.minor, p.amount.currency, p.note),
            )
        for tag in tx.tags:
            conn.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx_id, tag))
        return replace(tx, id=tx_id)

    def _ledger_for_adding(self):
        chart, paths = self._load_chart()
        return Ledger(chart), paths

    @_guard
    def add_transaction(self, tx):
        with self._txn(True):
            led, paths = self._ledger_for_adding()
            return self._insert(self._validated(led, paths, tx))

    @_guard
    def add_transactions(self, txs, keys=None):
        try:
            tx_list = list(txs)
        except TypeError:
            raise ValidationError("transactions must be a list") from None
        key_list = None
        if keys is not None:
            try:
                key_list = list(keys)
            except TypeError:
                raise ValidationError("keys must be a list of text") from None
            if len(key_list) != len(tx_list):
                raise ValidationError("keys must have one entry per transaction")
            for k in key_list:
                _need_text(k, "an import key")
        result = BulkAdd()
        with self._txn(True):
            led, paths = self._ledger_for_adding()
            seen = set()
            for i, tx in enumerate(tx_list):
                try:
                    if key_list is not None:
                        key = key_list[i]
                        if key in seen or self._has_key(key):
                            result.skipped.append(i)
                            continue
                    stored = self._insert(self._validated(led, paths, tx))
                    if key_list is not None:
                        self._conn.execute(
                            "INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, stored.id)
                        )
                        seen.add(key)
                except TallybookError as exc:
                    exc.detail["index"] = i
                    raise
                result.added.append(stored)
        return result

    def _has_key(self, key):
        return self._conn.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    @_guard
    def has_import_key(self, key):
        if not isinstance(key, str):
            return False
        with self._txn(False):
            return self._has_key(key)

    @staticmethod
    def _check_paging(limit, offset):
        if limit is not None and (not _is_int(limit) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0, got '%s'" % (limit,))
        if not _is_int(offset) or offset < 0:
            raise ValidationError("offset must be a whole number of at least 0, got '%s'" % (offset,))

    def _parse_query(self, query):
        if query is None:
            return None
        from .query import parse_query

        if isinstance(query, str):
            if not query.strip():
                return None
            return parse_query(query, self._load_chart()[0])
        if hasattr(query, "matches") and hasattr(query, "is_empty"):
            return None if query.is_empty else query
        raise ValidationError("query must be text or a parsed query, got '%s'" % (query,))

    @_guard
    def transactions(self, query=None, limit=None, offset=0):
        self._check_paging(limit, offset)
        with self._txn(False):
            q = self._parse_query(query)
            if q is None:
                return self._load("", (), limit, offset)
            from .query import select

            chosen = select(self._load(), q)
            return chosen[offset:] if limit is None else chosen[offset : offset + limit]

    @_guard
    def count_transactions(self, query=None):
        with self._txn(False):
            q = self._parse_query(query)
            if q is None:
                return self._conn.execute("SELECT count(*) FROM transactions").fetchone()[0]
            from .query import select

            return len(select(self._load(), q))

    @staticmethod
    def _need_id(tx_id):
        if not _is_int(tx_id):
            raise ValidationError("transaction id must be a whole number, got '%s'" % (tx_id,))

    @_guard
    def get_transaction(self, id):
        self._need_id(id)
        with self._txn(False):
            found = self._load("WHERE id = ?", (id,)) if _INT_MIN <= id <= _INT_MAX else []
            if not found:
                raise NotFoundError("no transaction %s" % id)
            return found[0]

    @_guard
    def delete_transaction(self, id):
        self._need_id(id)
        with self._txn(True):
            found = self._load("WHERE id = ?", (id,)) if _INT_MIN <= id <= _INT_MAX else []
            if not found:
                raise NotFoundError("no transaction %s" % id)
            for table in ("import_keys", "tags", "postings"):
                self._conn.execute("DELETE FROM %s WHERE tx_id = ?" % table, (id,))
            self._conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
            return found[0]

    def _build_ledger(self):
        chart, _ = self._load_chart()
        led = Ledger(chart, self._load_rates())
        for tx in self._load():
            try:
                led.add(tx)
            except TallybookError as exc:
                raise ConflictError("transaction %s is invalid: %s" % (tx.id, exc.message)) from None
        return led

    @_guard
    def ledger(self):
        with self._txn(False):
            return self._build_ledger()

    # -- rates -----------------------------------------------------------
    def _load_rates(self):
        table = RateTable()
        for src, dst, on, text in self._rate_rows():
            try:
                table.set(src, dst, text, on)
            except TallybookError as exc:
                raise ConflictError("the book holds an invalid rate %s -> %s: %s" % (src, dst, exc.message)) from None
        return table

    def _rate_rows(self):
        rows = self._conn.execute(
            "SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date"
        ).fetchall()
        return [(s, d, _parse_stored_date(o, "rate %s -> %s" % (s, d)), t) for s, d, o, t in rows]

    @_guard
    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        with self._txn(True):
            self._conn.execute(
                "INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                (src, dst, format_date(on), rate_text),
            )

    @_guard
    def remove_rate(self, src, dst, on):
        _need_text(src, "src")
        _need_text(dst, "dst")
        if not is_date(on):
            raise ValidationError("invalid date '%s': expected a date" % (on,))
        with self._txn(True):
            cur = self._conn.execute(
                "DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?", (src, dst, format_date(on))
            )
            if cur.rowcount == 0:
                raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))

    @_guard
    def rate_rows(self):
        with self._txn(False):
            return self._rate_rows()

    @_guard
    def rate_table(self):
        with self._txn(False):
            return self._load_rates()

    # -- budgets ---------------------------------------------------------
    @_guard
    def add_budget(self, budget):
        from .budgets import Budget

        if not isinstance(budget, Budget):
            raise ValidationError("not a budget: '%s'" % (budget,))
        _fit(budget.amount.minor, "the budget amount")
        with self._txn(True):
            exists = self._conn.execute(
                "SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                (budget.pattern, budget.period_kind),
            ).fetchone()
            if exists:
                raise ConflictError(
                    "a %s budget for '%s' already exists" % (budget.period_kind, budget.pattern)
                )
            self._conn.execute(
                "INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) VALUES (?, ?, ?, ?, ?)",
                (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency,
                 format_date(budget.start)),
            )

    @_guard
    def remove_budget(self, pattern, period_kind):
        _need_text(pattern, "pattern")
        _need_text(period_kind, "period kind")
        with self._txn(True):
            cur = self._conn.execute(
                "DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind)
            )
            if cur.rowcount == 0:
                raise NotFoundError("no %s budget for '%s'" % (period_kind, pattern))

    @_guard
    def budgets(self):
        from .budgets import Budget

        with self._txn(False):
            rows = self._conn.execute(
                "SELECT pattern, period_kind, minor, currency, start_date FROM budgets"
                " ORDER BY pattern, period_kind"
            ).fetchall()
            out = []
            for pattern, kind, minor, cur, start in rows:
                try:
                    out.append(
                        Budget(pattern, kind, Money(minor, cur), _parse_stored_date(start, "budget %s" % pattern))
                    )
                except ConflictError:
                    raise
                except TallybookError as exc:
                    raise ConflictError("the book holds an invalid budget '%s': %s" % (pattern, exc.message)) from None
            return out

    # -- recurring items -------------------------------------------------
    @staticmethod
    def _template_json(tx):
        from .export import transaction_to_dict

        data = transaction_to_dict(tx)
        data["tags"] = list(tx.tags)
        return json.dumps(data, sort_keys=True, ensure_ascii=False)

    @staticmethod
    def _template_from_json(text):
        from .export import transactions_from_json

        tx = transactions_from_json("[%s]" % text)[0]
        tx.tags = tuple(json.loads(text).get("tags", ()))
        return tx

    @_guard
    def add_recurring(self, rec):
        from .recurring import Recurring

        if not isinstance(rec, Recurring):
            raise ValidationError("not a recurring item: '%s'" % (rec,))
        template = self._template_json(rec.template)
        if rec.count is not None:
            _fit(rec.count, "the count")
        with self._txn(True):
            if self._conn.execute("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)).fetchone():
                raise ConflictError("a recurring item named '%s' already exists" % rec.name)
            self._conn.execute(
                "INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count)"
                " VALUES (?, ?, ?, ?, ?, ?)",
                (rec.name, str(rec.schedule), template, format_date(rec.start),
                 format_date(rec.end) if rec.end is not None else None, rec.count),
            )

    @_guard
    def remove_recurring(self, name):
        _need_text(name, "name")
        with self._txn(True):
            cur = self._conn.execute("DELETE FROM recurring WHERE name = ?", (name,))
            if cur.rowcount == 0:
                raise NotFoundError("no recurring item '%s'" % name)

    def _recurring_rows(self):
        from .recurring import Recurring

        out = []
        rows = self._conn.execute(
            "SELECT name, schedule, template, start_date, end_date, max_count, materialized_through"
            " FROM recurring ORDER BY name"
        ).fetchall()
        for name, schedule, template, start, end, count, through in rows:
            try:
                rec = Recurring(
                    name,
                    schedule,
                    self._template_from_json(template),
                    _parse_stored_date(start, "recurring %s" % name),
                    _parse_stored_date(end, "recurring %s" % name) if end else None,
                    count,
                )
            except ConflictError:
                raise
            except (TallybookError, ValueError) as exc:
                raise ConflictError(
                    "the book holds an invalid recurring item '%s': %s" % (name, getattr(exc, "message", exc))
                ) from None
            out.append((rec, _parse_stored_date(through, "recurring %s" % name) if through else None))
        return out

    @_guard
    def recurring(self):
        with self._txn(False):
            return [rec for rec, _ in self._recurring_rows()]

    @_guard
    def materialized_through(self, name):
        _need_text(name, "name")
        with self._txn(False):
            row = self._conn.execute(
                "SELECT materialized_through FROM recurring WHERE name = ?", (name,)
            ).fetchone()
            if row is None:
                raise NotFoundError("no recurring item '%s'" % name)
            return _parse_stored_date(row[0], "recurring %s" % name) if row[0] else None

    @_guard
    def materialize(self, upto=None, today=None):
        for value, what in ((upto, "upto"), (today, "today")):
            if value is not None and not is_date(value):
                raise ValidationError("%s must be a date, got '%s'" % (what, value))
        given = [d for d in (upto, today) if d is not None]
        if not given:
            raise ValidationError("materialize needs a date: give upto or today")
        horizon = min(given)
        from .recurring import instantiate, occurrences

        with self._txn(True):
            pending = []
            advance = []
            for rec, through in self._recurring_rows():
                if through is not None and horizon <= through:
                    continue
                lo = rec.start if through is None else through + timedelta(days=1)
                for day in occurrences(rec, lo, horizon):
                    pending.append((day, rec.name, instantiate(rec, day)))
                advance.append(rec.name)
            pending.sort(key=lambda item: (item[0], item[1]))
            led, paths = self._ledger_for_adding()
            made = [self._insert(self._validated(led, paths, tx)) for _, _, tx in pending]
            for name in advance:
                self._conn.execute(
                    "UPDATE recurring SET materialized_through = ? WHERE name = ?", (format_date(horizon), name)
                )
            return made

    # -- rules, settings, profiles ---------------------------------------
    @_guard
    def set_rules(self, text):
        from .rules import parse_rules

        _need_text(text, "rules")
        parse_rules(text)
        with self._txn(True):
            self._conn.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,))

    @_guard
    def rules_text(self):
        with self._txn(False):
            row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            return row[0] if row else ""

    @_guard
    def rules(self):
        from .rules import parse_rules

        with self._txn(False):
            row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            return parse_rules(row[0] if row else "")

    @staticmethod
    def _need_key(key):
        if not isinstance(key, str) or not key:
            raise ValidationError("a setting key must be non-empty text, got '%s'" % (key,))

    @_guard
    def get_setting(self, key, default=None):
        self._need_key(key)
        with self._txn(False):
            row = self._conn.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone()
            return default if row is None else row[0]

    @_guard
    def set_setting(self, key, value):
        self._need_key(key)
        _need_text(value, "a setting value")
        with self._txn(True):
            self._conn.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))

    @_guard
    def delete_setting(self, key):
        self._need_key(key)
        with self._txn(True):
            self._conn.execute("DELETE FROM settings WHERE key = ?", (key,))

    @_guard
    def settings(self):
        with self._txn(False):
            return {k: v for k, v in self._conn.execute("SELECT key, value FROM settings ORDER BY key")}

    @staticmethod
    def _need_profile_name(name):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise ValidationError(
                "invalid profile name '%s': use letters, digits, '_' and '-', starting with a letter or digit"
                % (name,)
            )

    @_guard
    def set_profile(self, name, text):
        from .csvimport import parse_profile

        self._need_profile_name(name)
        _need_text(text, "profile text")
        parse_profile(text)
        with self._txn(True):
            self._conn.execute(
                "INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (_PROFILE_PREFIX + name, text)
            )

    def _profile_text(self, name):
        row = None
        if isinstance(name, str) and _NAME_RE.fullmatch(name):
            row = self._conn.execute("SELECT value FROM settings WHERE key = ?", (_PROFILE_PREFIX + name,)).fetchone()
        if row is None:
            raise NotFoundError("no import profile '%s'" % (name,))
        return row[0]

    @_guard
    def profile_text(self, name):
        with self._txn(False):
            return self._profile_text(name)

    @_guard
    def profiles(self):
        with self._txn(False):
            keys = [k for (k,) in self._conn.execute("SELECT key FROM settings ORDER BY key")]
        names = [k[len(_PROFILE_PREFIX):] for k in keys if k.startswith(_PROFILE_PREFIX)]
        return sorted(n for n in names if _NAME_RE.fullmatch(n))

    @_guard
    def remove_profile(self, name):
        with self._txn(True):
            self._profile_text(name)
            self._conn.execute("DELETE FROM settings WHERE key = ?", (_PROFILE_PREFIX + name,))

    # -- CSV import and journals -----------------------------------------
    @_guard
    def import_csv(self, text, profile, apply_rules=True):
        from .csvimport import ImportProfile, import_csv, parse_profile
        from .rules import parse_rules

        with self._txn(True):
            if isinstance(profile, str):
                if _NAME_CHARS_RE.fullmatch(profile):
                    profile = parse_profile(self._profile_text(profile))
                else:
                    profile = parse_profile(profile)
            elif not isinstance(profile, ImportProfile):
                raise ValidationError("profile must be a profile name, profile text or an ImportProfile")
            rules = None
            if apply_rules:
                row = self._conn.execute("SELECT body FROM rules WHERE id = 1").fetchone()
                if row and row[0].strip():
                    rules = parse_rules(row[0])
            result = import_csv(text, profile, rules, self._load())
            outcome = ImportOutcome([], list(result.duplicates), list(result.errors))
            if result.errors or not result.transactions:
                return outcome
            counts = Counter(_import_key_base(tx) for tx in result.duplicates)
            keys = []
            for tx in result.transactions:
                base = _import_key_base(tx)
                counts[base] += 1
                keys.append("%s|%d" % (base, counts[base]))
            bulk = self.add_transactions(result.transactions, keys)
            outcome.added = bulk.added
            outcome.duplicates.extend(result.transactions[i] for i in bulk.skipped)
            return outcome

    @_guard
    def journal(self):
        from .journal import Journal

        with self._txn(False):
            return Journal(
                [self._load_chart()[0].get(p) for p in sorted(self._load_chart()[1])],
                self._rate_rows(),
                self._load(),
            )

    @_guard
    def load_journal(self, journal):
        for attr in ("accounts", "rates", "transactions"):
            if not hasattr(journal, attr):
                raise ValidationError("not a journal: '%s'" % (journal,))
        with self._txn(True):
            chart, paths = self._load_chart()
            led = Ledger(chart, self._load_rates())
            new_accounts = []
            for acct in journal.accounts:
                if not isinstance(acct, Account):
                    raise ValidationError("not an account: '%s'" % (acct,))
                if acct.path in paths:
                    raise ConflictError("account %s already exists" % acct.path)
                chart.add(acct.path, acct.type, acct.currency, acct.opened, acct.note)
                if acct.closed is not None:
                    chart.close(acct.path, acct.closed)
                paths.add(acct.path)
                new_accounts.append(chart.get(acct.path))
            rates = list(journal.rates)
            for src, dst, on, text in rates:
                led.rates.set(src, dst, text, on)
            checked = [self._validated(led, paths, tx) for tx in journal.transactions]
            for acct in new_accounts:
                self._conn.execute(
                    "INSERT INTO accounts (path, type, currency, opened, closed, note) VALUES (?, ?, ?, ?, ?, ?)",
                    (acct.path, acct.type, acct.currency,
                     format_date(acct.opened) if acct.opened else None,
                     format_date(acct.closed) if acct.closed else None, acct.note),
                )
            for src, dst, on, text in rates:
                self._conn.execute(
                    "INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                    (src, dst, format_date(on), text),
                )
            return [self._insert(tx) for tx in checked]

    # -- health, backup, status ------------------------------------------
    @_guard
    def check(self):
        problems = set()
        conn = self._conn
        with self._txn(False):
            try:
                for (msg,) in conn.execute("PRAGMA integrity_check").fetchall():
                    if msg != "ok":
                        problems.add("integrity check: %s" % msg)
                for tx_id, n in conn.execute(
                    "SELECT tx_id, count(*) FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"
                    " GROUP BY tx_id"
                ):
                    problems.add("transaction %s is missing but %d posting(s) point to it" % (tx_id, n))
                for tx_id, n in conn.execute(
                    "SELECT tx_id, count(*) FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"
                    " GROUP BY tx_id"
                ):
                    problems.add("transaction %s is missing but %d tag(s) point to it" % (tx_id, n))
                for key, tx_id in conn.execute(
                    "SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)"
                ):
                    problems.add("import key '%s' points to missing transaction %s" % (key, tx_id))
                for (tx_id,) in conn.execute(
                    "SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"
                ):
                    problems.add("transaction %s has no postings" % tx_id)
                for account, n in conn.execute(
                    "SELECT account, count(*) FROM postings WHERE account NOT IN (SELECT path FROM accounts)"
                    " GROUP BY account"
                ):
                    problems.add("%d posting(s) are on account '%s', which is not stored" % (n, account))
                sums = {}
                for tx_id, cur, minor in conn.execute(
                    "SELECT p.tx_id, p.currency, p.minor FROM postings p JOIN transactions t ON t.id = p.tx_id"
                ):
                    if not _is_int(minor):
                        problems.add("transaction %s has an amount that is not a whole number: %r" % (tx_id, minor))
                        continue
                    sums[(tx_id, cur)] = sums.get((tx_id, cur), 0) + minor
                for (tx_id, cur), total in sums.items():
                    if total != 0:
                        shown = format_minor(total, cur) if cur in CURRENCIES else str(total)
                        problems.add("transaction %s does not balance: %s %s" % (tx_id, cur, shown))
            except sqlite3.Error as exc:
                problems.add("cannot read the book: %s" % exc)
        return sorted(problems)

    @_guard
    def backup(self, dest):
        try:
            target = os.fspath(dest)
        except TypeError:
            raise ValidationError("destination must be text or a path object, got '%s'" % (dest,)) from None
        if isinstance(target, bytes):
            target = os.fsdecode(target)
        if not target:
            raise NotFoundError("no such directory for the backup")
        if os.path.lexists(target):
            raise ConflictError("'%s' already exists" % target)
        parent = os.path.dirname(os.path.abspath(target))
        if not os.path.isdir(parent):
            raise NotFoundError("the directory for '%s' does not exist" % target)
        try:
            fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
        except FileExistsError:
            raise ConflictError("'%s' already exists" % target) from None
        except OSError as exc:
            raise ConflictError("cannot create '%s': %s" % (target, exc.strerror or exc)) from None
        os.close(fd)
        try:
            out = sqlite3.connect(target, isolation_level=None)
            try:
                self._conn.backup(out)
            finally:
                out.close()
        except BaseException:
            self._discard(target)
            raise

    @_guard
    def info(self):
        with self._txn(False):
            counts = {}
            for table in ("accounts", "transactions", "postings", "rates", "budgets", "recurring"):
                counts[table] = self._conn.execute("SELECT count(*) FROM %s" % table).fetchone()[0]
        counts["path"] = self.path
        counts["version"] = self._version
        return counts

