            for table in ("accounts", "transactions", "postings", "rates", "budgets", "recurring"):
                counts[table] = self._conn.execute("SELECT count(*) FROM %s" % table).fetchone()[0]
        counts["path"] = self.path
        counts["version"] = self._version
        return counts

